import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int total = scanner.nextInt();
        int[] prefix = new int[5001];
        for (int i = 0; i < total; i++) {
            int val = scanner.nextInt();
            prefix[val]++;
        }
        int window_size = scanner.nextInt();
        for (int i = 1; i <= 3000; i++) {
            prefix[i] += prefix[i - 1];
        }
        int max_in_window = 0;
        for (int start_point = 1; start_point + window_size <= 5000; start_point++) {
            int current_window = prefix[start_point + window_size] - prefix[start_point - 1];
            if (current_window > max_in_window) {
                max_in_window = current_window;
            }
        }
        System.out.println(max_in_window);
        scanner.close();
    }
}
